{
  "headline": "FDA's records trace our supply to a plant classified OAI 49 days before the posting",
  "headline_cites": ["D9"],
  "sentences": [
    {
      "text": "FDA first posted the epinephrine shortage on 2012-02-22 and it remains Current as of 2026-10-21.",
      "cites": ["E38", "E37"]
    },
    {
      "text": "An FDA inspection of Hospira, Inc. (FEI 1925262) ended 2012-01-04 and was classified VAI, 49 days before the shortage posting.",
      "cites": ["D9", "E19"]
    },
    {
      "text": "A later inspection of the same Hospira plant ended 2016-06-08 and was classified OAI.",
      "cites": ["E24"]
    },
    {
      "text": "Another OAI inspection of Hospira ended 2018-08-15, with the classification known by FDA on 2020-04-22.",
      "cites": ["E26"]
    },
    {
      "text": "An import alert 66-66 was published 2009-09-30 for Boehringer Ingelheim Pharma GmbH & Co. KG (FEI 3002806556), 875 days before the shortage posting.",
      "cites": ["D8", "E16"]
    },
    {
      "text": "That Boehringer plant was inspected and classified OAI on 2012-11-12, 264 days after the shortage posting.",
      "cites": ["D11", "E9"]
    },
    {
      "text": "The rule‑based best option is to buy from Viatris Specialty LLC, which is not on FDA's shortage list today.",
      "cites": ["D16"]
    }
  ]
}
